def transform(grid):
    block = len(grid) // 8 if len(grid) == 24 else len(grid) // 3
    size = len(grid) // block
    out = [[0 for _ in range(size)] for _ in range(size)]
    for br in range(size):
        for bc in range(size):
            colors = {grid[r][c] for r in range(br * block, (br + 1) * block)
                      for c in range(bc * block, (bc + 1) * block)
                      if grid[r][c] not in (0, 5)}
            if colors:
                out[br][bc] = next(iter(colors))
    return out

def transform(grid):
    out = []
    for r in range(0, len(grid), 3):
        row = []
        for c in range(0, len(grid[0]), 3):
            colors = [grid[i][j] for i in range(r, r + 3) for j in range(c, c + 3)
                      if grid[i][j] not in (0, 5)]
            row.append(colors[0] if colors else 0)
        out.append(row)
    return out
